from functools import wraps

def makebold(fn):
 @wraps(fn)
 def wrapper(*args, **kwargs):
 return " " + fn(*args, **kwargs) + " "
 return wrapper

def makeitalic(fn):
 @wraps(fn)
 def wrapper(*args, **kwargs):
 return " " + fn(*args, **kwargs) + " "
 return wrapper

@makebold
@makeitalic
def hello():
