 const fetchMyAPI = useCallback(async () => {
 let response = await fetch('api/data/' + userId)
 response = await response.json()
 dataSet(response)
 }, [userId]) // if userId changes, useEffect will run again

 useEffect(() => {
 fetchMyAPI()
 }, [fetchMyAPI])

 return (

 data: {JSON.stringify(data)} 

