constructor(props) {
    super(props);

    this.state = {
        count : 1
    };

    this.delta = this.delta.bind(this);
}

constructor(props) {
    super(props);

    this.state = {
        count : 1
    };

}

delta = ()=> {
    this.setState({
        count : this.state.count++
    });
}

