solution:
You can roll your own, e.g. like this:

```
func unique (source: S) -> [T] where S.Iterator.Element == T {
 var buffer = [T]()
 var added = Set ()
 for elem in source {
 if !added.contains(elem) {
 buffer.append(elem)
 added.insert(elem)
 }
 }
 return buffer
}

let vals = [1, 4, 2, 2, 6, 24, 15, 2, 60, 15, 6]
let uniqueVals = uniq(vals) // [1, 4, 2, 6, 24, 15, 60]

```

 And as an extension for `Array`:

```
extension Array where Element: Hashable {
 func uniqued() -> Array {
 var buffer = Array()
 var added = Set ()
 for elem in self {
 if !added.contains(elem) {
 buffer.append(elem)
 added.insert(elem)
 }
 }
 return buffer
 }
}

```

 Or more elegantly (Swift 4/5):

```
extension Sequence where Element: Hashable {
 func uniqued() -> [Element] {
 var set = Set ()
 return filter { set.insert($0).inserted }
 }
}

```

 Which would be used:

```
[1,2,4,2,1].uniqued() // => [1,2,4]

```

code_example:
func unique<S : Sequence, T : Hashable>(source: S) -> [T] where S.Iterator.Element == T {
    var buffer = [T]()
    var added = Set<T>()
    for elem in source {
        if !added.contains(elem) {
            buffer.append(elem)
            added.insert(elem)
        }
    }
    return buffer
}

let vals = [1, 4, 2, 2, 6, 24, 15, 2, 60, 15, 6]
let uniqueVals = uniq(vals) // [1, 4, 2, 6, 24, 15, 60]

extension Array where Element: Hashable {
    func uniqued() -> Array {
        var buffer = Array()
        var added = Set<Element>()
        for elem in self {
            if !added.contains(elem) {
                buffer.append(elem)
                added.insert(elem)
            }
        }
        return buffer
    }
}

description:
In my Objective-C projects I often use a global constants file to store things like notification names and keys for `NSUserDefaults`. It looks something like this:

```
@interface GlobalConstants : NSObject

extern NSString *someNotification;

@end

@implementation GlobalConstants

NSString *someNotification = @"aaaaNotification";

@end

```

 How do I do exactly the same thing in Swift?

solution:
Structs as namespace

 IMO the best way to deal with that type of constants is to create a Struct.

```
struct Constants {
 static let someNotification = "TEST"
}

```

 Then, for example, call it like this in your code:

```
print(Constants.someNotification)

```

 Nesting

 If you want a better organization I advise you to use segmented sub structs

```
struct K {
 struct NotificationKey {
 static let Welcome = "kWelcomeNotif"
 }

 struct Path {
 static let Documents = NSSearchPathForDirectoriesInDomains(.DocumentDirectory, .UserDomainMask, true)[0] as String
 static let Tmp = NSTemporaryDirectory()
 }
}

```

 Then you can just use for instance `K.Path.Tmp` 

 Real world example

 This is just a technical solution, the actual implementation in my code looks more like:

```
struct GraphicColors {

 static let grayDark = UIColor(0.2)
 static let grayUltraDark = UIColor(0.1)

 static let brown = UIColor(rgb: 126, 99, 89)
 // etc.
}

```

 and 

```

enum Env: String {
 case debug
 case testFlight
