 name: 'my-component',
 data () {
 return {}
 }
}

```

 You can later import this and use it like:

```
// another-component.js




 import myComponent from 'my-component'
 export default {
 components: {
 myComponent
 }
 data () {
 return {}
 }
 ...
 }


```

 Also, be sure to declare your `data` properties as functions, otherwise they are not going to be reactive.

